"use client";

import { useState, useEffect, useMemo, useCallback } from "react";
import { showToast } from "@/components/ToastNotification";
import {
  Box,
  Button,
  Chip,
  Collapse,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  FormControl,
  IconButton,
  InputLabel,
  MenuItem,
  Paper,
  Select,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  TableSortLabel,
  TextField,
  Typography,
} from "@mui/material";
import { MoreVert, TrendingDown } from "@mui/icons-material";
import {
  getOutcomeListAction,
  createOutcomeAction,
  updateOutcomeAction,
  deleteOutcomeAction,
} from "@/features/outcome/actions";
import { getAccountsAction } from "@/features/account/actions";
import { getEnumsAction } from "@/features/enum/actions";
import {
  cellSx,
  headCellSx,
  inputSx,
  formatIDR,
  sortLabelSx,
  tableRowSx,
  tablePaperSx,
  popperStyles,
  dialogPaperSx,
  dialogTitleSx,
  dialogContentSx,
  dialogActionsSx,
  cancelBtnSx,
  saveBtnSx,
} from "@/lib/theme-shared";
import TableFilter from "@/components/TableFilter";
import PageHeader from "@/components/PageHeader";
import SummaryCards from "@/components/SummaryCards";
import DataTableToolbar from "@/components/DataTableToolbar";
import ActionMenu from "@/components/ActionMenu";
import ConfirmDeleteDialog from "@/components/ConfirmDeleteDialog";
import StyledTablePagination from "@/components/StyledTablePagination";
import TableSkeletonRows from "@/components/TableSkeletonRows";
import EmptyTableRow from "@/components/EmptyTableRow";
import { useDataRefresh } from "@/hooks/useDataRefresh";
import { useQueryParams, readQueryParams } from "@/hooks/useQueryParams";
import { LocalizationProvider } from "@mui/x-date-pickers/LocalizationProvider";
import { AdapterDateFns } from "@mui/x-date-pickers/AdapterDateFns";
import { DatePicker } from "@mui/x-date-pickers/DatePicker";
import { parseISO, format } from "date-fns";
import type { OutcomeRow } from "@/types/transaction.type";

const kategoriColor: Record<string, string> = {
  "Kebutuhan Pokok": "#f59e0b",
  Transportasi: "#3b82f6",
  Utilitas: "#8b5cf6",
  Hiburan: "#ec4899",
  Kesehatan: "#10b981",
  Pendidikan: "#06b6d4",
  Investasi: "#22c55e",
  Lainnya: "#64748b",
};

const COLUMNS = [
  { id: "id" as const, label: "ID" },
  { id: "tanggal" as const, label: "Tanggal" },
  { id: "kategori" as const, label: "Kategori" },
  { id: "subkategori" as const, label: "Subkategori" },
  { id: "akun" as const, label: "Akun" },
  { id: "nominal" as const, label: "Nominal" },
  { id: "catatan" as const, label: "Catatan" },
];

const SKELETON_WIDTHS = [50, 80, 70, 70, 70, 60, 100, 40];

// ─── Component ────────────────────────────────────────────────────────────────
export default function OutcomePage() {
  const [rows, setRows] = useState<OutcomeRow[]>([]);
  const [loading, setLoading] = useState(true);

  const [accounts, setAccounts] = useState<{ id: number; name: string }[]>([]);
  const [categories, setCategories] = useState<{ id: number; value: string }[]>([]);
  const [subcategories, setSubcategories] = useState<{ id: number; value: string; parentId?: number }[]>([]);

  const accountMap = useMemo(() => Object.fromEntries(accounts.map((a) => [a.id, a.name])), [accounts]);
  const categoryMap = useMemo(() => Object.fromEntries(categories.map((c) => [c.id, c.value])), [categories]);
  const subcategoryMap = useMemo(() => Object.fromEntries(subcategories.map((s) => [s.id, s.value])), [subcategories]);

  const [search, setSearch] = useState("");
  const [page, setPage] = useState(0);
  const [rowsPerPage, setRowsPerPage] = useState(10);
  const [orderBy, setOrderBy] = useState<keyof OutcomeRow>("tanggal");
  const [order, setOrder] = useState<"asc" | "desc">("desc");
  const [actionAnchor, setActionAnchor] = useState<{ el: HTMLElement; row: OutcomeRow } | null>(null);
  const [deleteDialogOpen, setDeleteDialogOpen] = useState(false);
  const [rowToDelete, setRowToDelete] = useState<OutcomeRow | null>(null);
  const [formOpen, setFormOpen] = useState(false);
  const [editRow, setEditRow] = useState<OutcomeRow | null>(null);

  const [activeFilters, setActiveFilters] = useState<Record<string, string | number>>({
    accountId: "",
    categoryId: "",
    subcategoryId: "",
  });
  const [startDate, setStartDate] = useState("");
  const [endDate, setEndDate] = useState("");
  const [filterOpen, setFilterOpen] = useState(false);

  const [form, setForm] = useState<any>({
    tanggal: new Date().toISOString().split("T")[0],
    categoryId: 0,
    subcategoryId: 0,
    accountId: 0,
    amount: "",
    note: "",
  });

  // ─── Data Loading ─────────────────────────────────────────────────────────
  const loadData = useCallback(async () => {
    try {
      setLoading(true);
      const [accRes, catRes, subRes, rowsRes] = await Promise.all([
        getAccountsAction(),
        getEnumsAction('outcome_category'),
        getEnumsAction('outcome_subcategory'),
        getOutcomeListAction({ page: 1, pageSize: 100 }),
      ]);

      let currentAccounts: any[] = [];
      let currentCategories: any[] = [];
      let currentSubcategories: any[] = [];

      if (accRes.success) { setAccounts(accRes.data as any[]); currentAccounts = accRes.data; }
      if (catRes.success) { setCategories(catRes.data as any[]); currentCategories = catRes.data; }
      if (subRes.success) { setSubcategories(subRes.data as any[]); currentSubcategories = subRes.data; }

      const currentAccountMap = Object.fromEntries(currentAccounts.map((a: any) => [a.id, a.name]));
      const currentCategoryMap = Object.fromEntries(currentCategories.map((c: any) => [c.id, c.value]));
      const currentSubcategoryMap = Object.fromEntries(currentSubcategories.map((s: any) => [s.id, s.value]));

      if (rowsRes.success) {
        const items = rowsRes.data.items as any[];
        setRows(
          items.map((o) => ({
            id: `OUT-${String(o.id).padStart(3, '0')}`,
            tanggal: o.date,
            kategori: currentCategoryMap[o.categoryId] || '',
            subkategori: currentSubcategoryMap[o.subcategoryId] || '',
            akun: currentAccountMap[o.accountId] || '',
            nominal: Number(o.amount) || 0,
            catatan: o.note || '',
            raw: o,
          }))
        );
      }
    } catch (err) {
      console.error('failed to load initial data', err);
    } finally {
      setLoading(false);
    }
  }, []);

  const loadRows = useCallback(async () => {
    try {
      setLoading(true);
      const json = await getOutcomeListAction({ page: 1, pageSize: 100 });
      if (json.success) {
        setRows(
          (json.data.items as any[]).map((o) => ({
            id: `OUT-${String(o.id).padStart(3, '0')}`,
            tanggal: o.date,
            kategori: categoryMap[o.categoryId] || '',
            subkategori: subcategoryMap[o.subcategoryId] || '',
            akun: accountMap[o.accountId] || '',
            nominal: Number(o.amount) || 0,
            catatan: o.note || '',
            raw: o,
          }))
        );
      }
    } catch (err) {
      console.error('failed to load outcomes', err);
    } finally {
      setLoading(false);
    }
  }, [categoryMap, subcategoryMap, accountMap]);

  useEffect(() => { loadData(); }, [loadData]);
  useDataRefresh(loadData);

  // ─── URL Sync ─────────────────────────────────────────────────────────────
  useEffect(() => {
    if (typeof window === "undefined") return;
    const params = readQueryParams();
    const urlSearch = params.get("search") || "";
    const urlAccountId = params.get("accountId") ? Number(params.get("accountId")) || params.get("accountId")! : "";
    const urlCategoryId = params.get("categoryId") ? Number(params.get("categoryId")) || params.get("categoryId")! : "";
    const urlSubcategoryId = params.get("subcategoryId") ? Number(params.get("subcategoryId")) || params.get("subcategoryId")! : "";
    const urlStartDate = params.get("startDate") || "";
    const urlEndDate = params.get("endDate") || "";

    if (urlSearch) setSearch(urlSearch);
    if (urlAccountId || urlCategoryId || urlSubcategoryId) {
      setActiveFilters({ accountId: urlAccountId, categoryId: urlCategoryId, subcategoryId: urlSubcategoryId });
      setFilterOpen(true);
    }
    if (urlStartDate) { setStartDate(urlStartDate); setFilterOpen(true); }
    if (urlEndDate) { setEndDate(urlEndDate); setFilterOpen(true); }
  }, []);

  useQueryParams({
    search,
    ...(activeFilters.accountId ? { accountId: String(activeFilters.accountId) } : {}),
    ...(activeFilters.categoryId ? { categoryId: String(activeFilters.categoryId) } : {}),
    ...(activeFilters.subcategoryId ? { subcategoryId: String(activeFilters.subcategoryId) } : {}),
    ...(startDate ? { startDate } : {}),
    ...(endDate ? { endDate } : {}),
  });

  // ─── Filtering & Sorting ─────────────────────────────────────────────────
  const filtered = rows
    .filter((r) => {
      const q = search.toLowerCase();
      const matchesSearch = r.id.toLowerCase().includes(q) || r.kategori.toLowerCase().includes(q) || r.subkategori.toLowerCase().includes(q) || r.akun.toLowerCase().includes(q) || r.catatan.toLowerCase().includes(q);
      if (!matchesSearch) return false;
      if (activeFilters.accountId && r.raw?.accountId !== activeFilters.accountId) return false;
      if (activeFilters.categoryId && r.raw?.categoryId !== activeFilters.categoryId) return false;
      if (activeFilters.subcategoryId && r.raw?.subcategoryId !== activeFilters.subcategoryId) return false;
      if (startDate && new Date(r.tanggal) < new Date(startDate)) return false;
      if (endDate && new Date(r.tanggal) > new Date(endDate)) return false;
      return true;
    })
    .sort((a, b) => {
      const av = a[orderBy], bv = b[orderBy];
      if (av < bv) return order === "asc" ? -1 : 1;
      if (av > bv) return order === "asc" ? 1 : -1;
      return 0;
    });

  const paginated = filtered.slice(page * rowsPerPage, page * rowsPerPage + rowsPerPage);
  const totalNominal = filtered.reduce((s, r) => s + r.nominal, 0);

  const handleSort = (col: keyof OutcomeRow) => {
    if (orderBy === col) setOrder(order === "asc" ? "desc" : "asc");
    else { setOrderBy(col); setOrder("asc"); }
    setPage(0);
  };

  // ─── CRUD Handlers ────────────────────────────────────────────────────────
  const handleDelete = async () => {
    if (!rowToDelete) return;
    try {
      const idNum = parseInt(rowToDelete.id.replace(/^OUT-/, ''), 10);
      await deleteOutcomeAction(idNum);
      showToast("Data pengeluaran berhasil dihapus!", "success");
      loadRows();
    } catch (err) {
      console.error('delete outcome error', err);
      showToast("Gagal menghapus data pengeluaran.", "error");
    }
    setDeleteDialogOpen(false);
    setActionAnchor(null);
  };

  const openAdd = () => {
    setEditRow(null);
    setForm({ tanggal: new Date().toISOString().split("T")[0], categoryId: categories[0]?.id || 0, subcategoryId: 0, accountId: accounts[0]?.id || 0, amount: "", note: "" });
    setFormOpen(true);
  };

  const openEdit = (row: OutcomeRow) => {
    setEditRow(row);
    const raw = (row as any).raw;
    setForm({ tanggal: raw.date, categoryId: raw.categoryId, subcategoryId: raw.subcategoryId, accountId: raw.accountId, amount: String(raw.amount), note: raw.note || "" });
    setFormOpen(true);
    setActionAnchor(null);
  };

  const handleSave = async () => {
    if (!form.amount) return;
    try {
      if (editRow) {
        const idNum = parseInt(editRow.id.replace(/^OUT-/, ''), 10);
        await updateOutcomeAction({ id: idNum, ...form, date: form.tanggal });
        showToast("Pengeluaran berhasil diperbarui!", "success");
      } else {
        await createOutcomeAction({ date: form.tanggal, categoryId: form.categoryId, subcategoryId: form.subcategoryId, accountId: form.accountId, amount: Number(form.amount), note: form.note });
        showToast("Pengeluaran berhasil ditambahkan!", "success");
      }
      await loadRows();
    } catch (err) {
      console.error('save outcome error', err);
      showToast("Gagal menyimpan data pengeluaran.", "error");
    }
    setFormOpen(false);
  };

  const totalThisMonth = rows.filter((r) => r.tanggal.startsWith("2025-03")).reduce((s, r) => s + r.nominal, 0);
  const avgOutcome = rows.length > 0 ? rows.reduce((s, r) => s + r.nominal, 0) / rows.length : 0;
  const hasActiveFilters = Object.values(activeFilters).some((v) => v !== "") || !!startDate || !!endDate;

  return (
    <Box sx={{ p: { xs: 3, md: 4 }, minHeight: "100vh" }}>
      <PageHeader title="Outcome" subtitle="Kelola dan pantau seluruh data pengeluaran" icon={<TrendingDown sx={{ fontSize: 18, color: "#ef4444" }} />} iconBgColor="rgba(239,68,68,0.12)" />

      <SummaryCards cards={[
        { label: "Total Pengeluaran", value: formatIDR(rows.reduce((s, r) => s + r.nominal, 0)), sub: `${rows.length} transaksi`, color: "#ef4444" },
        { label: "Bulan Ini (Mar)", value: formatIDR(totalThisMonth), sub: "Maret 2025", color: "#ef4444" },
        { label: "Rata-rata Transaksi", value: formatIDR(avgOutcome), sub: "Per transaksi", color: "#ef4444" },
      ]} />

      <Paper elevation={0} sx={tablePaperSx}>
        <DataTableToolbar
          search={search} onSearchChange={(v) => { setSearch(v); setPage(0); }}
          resultCount={filtered.length} resultTotal={formatIDR(totalNominal)}
          filterOpen={filterOpen} onFilterToggle={() => setFilterOpen(!filterOpen)}
          onResetFilters={() => { setActiveFilters({ accountId: "", categoryId: "", subcategoryId: "" }); setStartDate(""); setEndDate(""); }}
          hasActiveFilters={hasActiveFilters} onAdd={openAdd} searchPlaceholder="Cari pengeluaran..."
        />

        <Collapse in={filterOpen}>
          <Box sx={{ px: 3, pb: 2 }}>
            <TableFilter
              options={[
                { key: "accountId", label: "Akun", options: accounts.map((a) => ({ id: a.id, name: a.name })) },
                { key: "categoryId", label: "Kategori", options: categories.map((c) => ({ id: c.id, name: c.value })) },
                { key: "subcategoryId", label: "Subkategori", options: subcategories.map((s) => ({ id: s.id, name: s.value })) },
              ]}
              activeFilters={activeFilters}
              onFilterChange={(key, val) => setActiveFilters((prev) => ({ ...prev, [key]: val }))}
              startDate={startDate} endDate={endDate} onStartDateChange={setStartDate} onEndDateChange={setEndDate}
            />
          </Box>
        </Collapse>

        <TableContainer>
          <Table size="small">
            <TableHead>
              <TableRow>
                {COLUMNS.map((col) => (
                  <TableCell key={col.id} sx={headCellSx}>
                    <TableSortLabel active={orderBy === col.id} direction={orderBy === col.id ? order : "asc"} onClick={() => handleSort(col.id)} sx={sortLabelSx}>{col.label}</TableSortLabel>
                  </TableCell>
                ))}
                <TableCell sx={{ ...headCellSx, textAlign: "center" }}>Aksi</TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {loading ? (
                <TableSkeletonRows columns={SKELETON_WIDTHS} />
              ) : paginated.length === 0 ? (
                <EmptyTableRow colSpan={8} />
              ) : (
                paginated.map((row, i) => (
                  <TableRow key={row.id} sx={tableRowSx(i)}>
                    <TableCell sx={{ ...cellSx, color: "#6366f1", fontWeight: 600, fontFamily: "monospace", fontSize: "0.75rem" }}>{row.id}</TableCell>
                    <TableCell sx={cellSx}>{new Date(row.tanggal).toLocaleDateString("id-ID", { day: "2-digit", month: "short", year: "numeric" })}</TableCell>
                    <TableCell sx={cellSx}>
                      <Box sx={{ display: "flex", alignItems: "center", gap: 1 }}>
                        <Box sx={{ width: 8, height: 8, borderRadius: "50%", backgroundColor: kategoriColor[row.kategori] || "#64748b", flexShrink: 0 }} />
                        <Typography sx={{ fontSize: "0.8125rem", color: "#cbd5e1" }}>{row.kategori}</Typography>
                      </Box>
                    </TableCell>
                    <TableCell sx={cellSx}>
                      {row.subkategori ? <Chip label={row.subkategori} size="small" variant="filled" sx={{ fontSize: "0.6875rem", height: 22, fontWeight: 500, borderRadius: "6px", backgroundColor: "rgba(71,85,105,0.4)", color: "#94a3b8" }} /> : <Typography sx={{ color: "#334155", fontSize: "0.8rem" }}>—</Typography>}
                    </TableCell>
                    <TableCell sx={cellSx}>
                      <Chip label={row.akun} size="small" variant="filled" sx={{ fontSize: "0.6875rem", height: 22, fontWeight: 500, borderRadius: "6px", backgroundColor: "rgba(71,85,105,0.4)", color: "#94a3b8" }} />
                    </TableCell>
                    <TableCell sx={{ ...cellSx, color: "#ef4444", fontWeight: 600, whiteSpace: "nowrap" }}>{formatIDR(row.nominal)}</TableCell>
                    <TableCell sx={{ ...cellSx, color: "#64748b", maxWidth: 200, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{row.catatan || "—"}</TableCell>
                    <TableCell sx={{ ...cellSx, textAlign: "center" }}>
                      <IconButton size="small" onClick={(e) => setActionAnchor({ el: e.currentTarget, row })} sx={{ color: "#475569", "&:hover": { color: "#c7d2fe", bgcolor: "rgba(99,102,241,0.1)" } }}><MoreVert fontSize="small" /></IconButton>
                    </TableCell>
                  </TableRow>
                ))
              )}
            </TableBody>
          </Table>
        </TableContainer>

        <StyledTablePagination count={filtered.length} page={page} rowsPerPage={rowsPerPage} onPageChange={(_, p) => setPage(p)} onRowsPerPageChange={(e) => { setRowsPerPage(parseInt(e.target.value, 10)); setPage(0); }} />
      </Paper>

      <ActionMenu anchorEl={actionAnchor?.el ?? null} open={Boolean(actionAnchor)} onClose={() => setActionAnchor(null)} onEdit={() => { if (actionAnchor) openEdit(actionAnchor.row); }} onDelete={() => { if (actionAnchor) { setRowToDelete(actionAnchor.row); setDeleteDialogOpen(true); } }} />

      <Dialog open={formOpen} onClose={() => setFormOpen(false)} PaperProps={dialogPaperSx}>
        <DialogTitle sx={dialogTitleSx}>{editRow ? "Edit Pengeluaran" : "Tambah Pengeluaran"}</DialogTitle>
        <DialogContent sx={dialogContentSx}>
          <LocalizationProvider dateAdapter={AdapterDateFns}>
            <DatePicker label="Tanggal" value={form.tanggal ? parseISO(form.tanggal) : null} onChange={(newVal) => { if (newVal) setForm({ ...form, tanggal: format(newVal as Date, "yyyy-MM-dd") }); }}
              slotProps={{ textField: { size: "small", fullWidth: true }, popper: { sx: popperStyles } }} />
          </LocalizationProvider>
          <FormControl size="small" fullWidth><InputLabel sx={{ color: "#64748b" }}>Kategori</InputLabel><Select value={form.categoryId} label="Kategori" onChange={(e) => setForm({ ...form, categoryId: Number(e.target.value), subcategoryId: 0 })} sx={inputSx}>{categories.map((c) => <MenuItem key={c.id} value={c.id}>{c.value}</MenuItem>)}</Select></FormControl>
          <FormControl size="small" fullWidth><InputLabel sx={{ color: "#64748b" }}>Subkategori</InputLabel><Select value={form.subcategoryId} label="Subkategori" onChange={(e) => setForm({ ...form, subcategoryId: Number(e.target.value) })} sx={inputSx}>{subcategories.filter((s) => s.parentId === form.categoryId).map((s) => <MenuItem key={s.id} value={s.id}>{s.value}</MenuItem>)}</Select></FormControl>
          <FormControl size="small" fullWidth><InputLabel sx={{ color: "#64748b" }}>Akun</InputLabel><Select value={form.accountId} label="Akun" onChange={(e) => setForm({ ...form, accountId: Number(e.target.value) })} sx={inputSx}>{accounts.map((a) => <MenuItem key={a.id} value={a.id}>{a.name}</MenuItem>)}</Select></FormControl>
          <TextField label="Nominal (IDR)" size="small" fullWidth type="number" value={form.amount} onChange={(e) => setForm({ ...form, amount: e.target.value })} InputLabelProps={{ sx: { color: "#64748b" } }} InputProps={{ sx: inputSx }} />
          <TextField label="Catatan" size="small" fullWidth multiline rows={2} value={form.note} onChange={(e) => setForm({ ...form, note: e.target.value })} InputLabelProps={{ sx: { color: "#64748b" } }} InputProps={{ sx: inputSx }} />
        </DialogContent>
        <DialogActions sx={dialogActionsSx}>
          <Button onClick={() => setFormOpen(false)} size="small" sx={cancelBtnSx}>Batal</Button>
          <Button onClick={handleSave} size="small" variant="contained" sx={saveBtnSx}>{editRow ? "Simpan" : "Tambah"}</Button>
        </DialogActions>
      </Dialog>

      <ConfirmDeleteDialog open={deleteDialogOpen} onClose={() => setDeleteDialogOpen(false)} onConfirm={handleDelete} itemId={rowToDelete?.id} />
    </Box>
  );
}